-- STA 122: Inference II  (old code STA 132)
-- =============================================================================
-- 68 questions, every answer computed. Built from the Inference II lecture notes
-- (sampling distributions, tests of significance, one- and two-sample tests of
-- means and proportions) and the STA 132 CA filler topics (regression and
-- correlation, time series). Stems and numbers were worked independently;
-- the printed CA answer key lists answers only, with no questions, so it was
-- used only to cover the same topics.
-- Replaces the placeholder subject 'sta-132-coming-soon' (renamed STA 122).
-- ASSUMPTIONS: 100 Level, second semester, 2 units. Faculties follow the
-- outline rows for Statistics, Mathematics, Computer Science and Economics.
-- =============================================================================

delete from public.cbt_questions where subject_id in ('sta-132-coming-soon', 'sta-122-inference-ii');

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A population consists of the values 1, 2, 3 and 4. How many different random samples of size 2 can be drawn without replacement?', '["6","4","8","12"]'::jsonb, 0, 'Without replacement and ignoring order, the number of samples is $\binom{4}{2} = 6$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the population 1, 2, 3, 4, the mean of all possible sample means (samples of size 2 without replacement) is:', '["2.0","2.5","3.0","1.5"]'::jsonb, 1, 'The mean of the sampling distribution of $\bar{x}$ equals the population mean: $(1+2+3+4)/4 = 2.5$. This shows $\bar{x}$ is an unbiased estimator of $\mu$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The population 1, 2, 3, 4 has variance (with divisor $N-1$) $S^{2} = $', '["1.2500","0.4167","1.6667","2.5000"]'::jsonb, 2, 'Squared deviations from 2.5 are 2.25, 0.25, 0.25 and 2.25, which sum to 5. Dividing by $N - 1 = 3$ gives $1.6667$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For samples of size 2 drawn without replacement from the population 1, 2, 3, 4, the variance of the sample mean is:', '["0.83333","1.66667","0.62500","0.41667"]'::jsonb, 3, 'Using $\sigma_{\bar{x}}^{2} = \dfrac{N-n}{N}\cdot\dfrac{S^{2}}{n} = \dfrac{2}{4}\cdot\dfrac{1.6667}{2} = 0.41667$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If sampling is done WITH replacement, the variance of the sample mean $\bar{x}$ is:', '["$\\sigma^{2}/n$","$\\sigma^{2}\\,(N-n)/N$","$\\sigma\\sqrt{n}$","$n\\sigma^{2}$"]'::jsonb, 0, 'With replacement (or from an infinite population) the finite-population correction is not needed, so $\mathrm{Var}(\bar{x}) = \sigma^{2}/n$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The sample mean $\bar{x}$ is an unbiased estimator of the population mean $\mu$ because:', '["$\\mathrm{Var}(\\bar{x}) = \\mu$","$E(\\bar{x}) = \\mu$","$E(\\bar{x}) = \\sigma$","$\\bar{x}$ is always equal to $\\mu$"]'::jsonb, 1, 'An estimator is unbiased when its expected value equals the parameter it estimates.', 'Properties of Estimators', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A random sample is taken from a normal distribution with mean $\mu$ and variance $\sigma^{2}$. The sampling distribution of the sample mean is:', '["normal with mean $\\mu$ and variance $\\sigma^{2}$","normal with mean $\\mu/n$ and variance $\\sigma^{2}$","normal with mean $\\mu$ and variance $\\sigma^{2}/n$","not normal unless $n \\geq 100$"]'::jsonb, 2, 'If the parent population is normal, $\bar{x}$ is exactly normal for every sample size.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The standard deviation of the sampling distribution of a statistic is called the:', '["sample variance","population parameter","critical value","standard error"]'::jsonb, 3, 'The standard error is the standard deviation of the sampling distribution of an estimator.', 'Standard Error', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean monthly spending of 2,500 students is N260 with standard deviation N8. If 100 students are selected at random WITH replacement, the variance of the sample mean is:', '["0.64","0.80","6.40","0.08"]'::jsonb, 0, '$\sigma_{\bar{x}}^{2} = \sigma^{2}/n = 64/100 = 0.64$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean monthly spending of 2,500 students is N260 with standard deviation N8. If 100 students are selected WITHOUT replacement, the variance of the sample mean is approximately:', '["0.640","0.615","0.960","0.064"]'::jsonb, 1, '$\sigma_{\bar{x}}^{2} = \dfrac{N-n}{N-1}\cdot\dfrac{\sigma^{2}}{n} = \dfrac{2400}{2499}(0.64) \approx 0.615$.', 'Sampling Distribution of the Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two independent groups of students have mean scores 69% (variance 42, sample 28) and 58% (variance 72, sample 36). The mean of the sampling distribution of the difference in sample means $\bar{x}_{1} - \bar{x}_{2}$ is:', '["127%","1.1%","11%","3.5%"]'::jsonb, 2, '$\mu_{\bar{x}_1 - \bar{x}_2} = \mu_1 - \mu_2 = 69 - 58 = 11$.', 'Sampling Distribution of the Difference of Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same two groups (sampling with replacement), the variance of $\bar{x}_{1} - \bar{x}_{2}$ is:', '["114.0","11.0","1.5","3.5"]'::jsonb, 3, '$\sigma^{2} = \dfrac{\sigma_{1}^{2}}{n_{1}} + \dfrac{\sigma_{2}^{2}}{n_{2}} = \dfrac{42}{28} + \dfrac{72}{36} = 1.5 + 2 = 3.5$.', 'Sampling Distribution of the Difference of Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The variance of the SUM of two independent sample means, $\bar{x}_{1} + \bar{x}_{2}$, is:', '["$\\dfrac{\\sigma_{1}^{2}}{n_{1}} + \\dfrac{\\sigma_{2}^{2}}{n_{2}}$","$\\dfrac{\\sigma_{1}^{2}}{n_{1}} - \\dfrac{\\sigma_{2}^{2}}{n_{2}}$","$\\dfrac{\\sigma_{1}^{2} + \\sigma_{2}^{2}}{n_{1} + n_{2}}$","$\\dfrac{\\sigma_{1}\\sigma_{2}}{n_{1}n_{2}}$"]'::jsonb, 0, 'Variances of independent quantities add whether they are summed or subtracted.', 'Sampling Distribution of the Difference of Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A population proportion is $\pi = 0.72$. For samples of size 80 drawn with replacement, the variance of the sample proportion is:', '["0.00900","0.00252","0.00210","0.01440"]'::jsonb, 1, '$\mathrm{Var}(p) = \pi(1 - \pi)/n = 0.72(0.28)/80 = 0.00252$.', 'Sampling Distribution of a Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In a ward with 519 votes, 72% were for one party. For a sample of 80 voters drawn WITHOUT replacement, the variance of the sample proportion is approximately:', '["0.00252","0.00420","0.00214","0.00110"]'::jsonb, 2, '$\mathrm{Var}(p) = \dfrac{N-n}{N-1}\cdot\dfrac{\pi(1-\pi)}{n} = \dfrac{439}{518}(0.00252) \approx 0.00214$.', 'Sampling Distribution of a Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The sampling distribution of the sample proportion $p$ is approximately normal when:', '["$n < 10$","$\\pi = 0$","$\\pi$ is close to 1 and $n$ is small","$n$ is large and $\\pi$ is not close to 0 or 1"]'::jsonb, 3, 'A normal approximation needs a large sample and a proportion away from the extremes.', 'Sampling Distribution of a Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean of the sampling distribution of the difference between two sample proportions, $p_{1} - p_{2}$, is:', '["$\\pi_{1} - \\pi_{2}$","$\\pi_{1} + \\pi_{2}$","$\\pi_{1}\\pi_{2}$","$(\\pi_{1} - \\pi_{2})/2$"]'::jsonb, 0, 'Each sample proportion is unbiased for its population proportion, so the difference is unbiased for $\pi_1 - \pi_2$.', 'Sampling Distribution of the Difference of Proportions', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two wards have proportions $\pi_{1} = 0.72$ ($n_1 = 80$) and $\pi_{2} = 0.59$ ($n_2 = 100$). With replacement, the variance of $p_{1} - p_{2}$ is approximately:', '["0.01300","0.00494","0.00252","0.00420"]'::jsonb, 1, '$\dfrac{0.72(0.28)}{80} + \dfrac{0.59(0.41)}{100} = 0.00252 + 0.00242 = 0.00494$.', 'Sampling Distribution of the Difference of Proportions', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A statistical hypothesis is best described as:', '["a proven fact about a sample","the mean of a sample","an assumption about a parameter or the probability distribution of a population","the error in an estimate"]'::jsonb, 2, 'A hypothesis is a claim about a population that can be tested with sample evidence.', 'Hypothesis Testing Concepts', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The null hypothesis $H_{0}$ is:', '["the hypothesis the researcher hopes is true","always a one-sided statement","the same as the sample statistic","the hypothesis being tested, usually formulated in order to be rejected"]'::jsonb, 3, '$H_0$ is the statement under test; the alternative $H_1$ is what is accepted if $H_0$ is rejected.', 'Hypothesis Testing Concepts', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A Type I error occurs when:', '["a true null hypothesis is rejected","a false null hypothesis is accepted","a true null hypothesis is accepted","a false null hypothesis is rejected"]'::jsonb, 0, 'Type I: rejecting a true $H_0$. Type II: accepting a false $H_0$.', 'Types of Error', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A Type II error occurs when:', '["a true null hypothesis is rejected","a false null hypothesis is accepted","the sample is too small to calculate a mean","the level of significance is 5%"]'::jsonb, 1, 'A Type II error is failing to reject a null hypothesis that is actually false.', 'Types of Error', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The maximum probability of committing a Type I error that a researcher is willing to accept is called the:', '["power of the test","critical value","level of significance","acceptance region"]'::jsonb, 2, 'It is denoted by $\alpha$.', 'Level of Significance', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A level of significance of $\alpha = 0.05$ means that:', '["the test is wrong 95% of the time","the null hypothesis is 5% likely to be true","the sample must contain 5% of the population","in about 5 out of every 100 cases a true null hypothesis would be rejected"]'::jsonb, 3, '$\alpha$ is the long-run chance of rejecting a true $H_0$.', 'Level of Significance', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A test is two-tailed when the alternative hypothesis is stated as:', '["$H_{1}: \\mu \\neq \\mu_{0}$","$H_{1}: \\mu > \\mu_{0}$","$H_{1}: \\mu < \\mu_{0}$","$H_{1}: \\mu = \\mu_{0}$"]'::jsonb, 0, 'A two-tailed test looks for a difference in either direction.', 'Types of Test', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The test of $H_{0}: \mu = 1500$ against $H_{1}: \mu < 1500$ is a:', '["two-tailed test","one-tailed (left-tailed) test","right-tailed test","test of proportion"]'::jsonb, 1, 'The alternative points to one side only (smaller than the claimed mean).', 'Types of Test', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The value that separates the critical region from the acceptance region is called the:', '["test statistic","standard error","critical value","estimator"]'::jsonb, 2, 'If the test statistic falls beyond the critical value, $H_0$ is rejected.', 'Critical Region', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The critical (rejection) region of a test is:', '["the set of outcomes that leads to acceptance of $H_{0}$","the sample mean","the population variance","the set of sample outcomes that leads to rejection of $H_{0}$"]'::jsonb, 3, 'The acceptance region is the complement.', 'Critical Region', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Which step comes right after choosing the level of significance in a test of hypothesis?', '["choosing the appropriate test statistic","stating the conclusion","computing the standard error of the population","deciding the sample mean"]'::jsonb, 0, 'Order: state $H_0$ and $H_1$; choose $\alpha$; choose the test statistic; set the decision rule; compute and decide.', 'Procedure for Testing Hypotheses', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For a one-sample test of the mean with known population variance from a normal population, the test statistic is:', '["$t = \\dfrac{\\bar{x} - \\mu}{S\\sqrt{n}}$","$Z = \\dfrac{\\bar{x} - \\mu}{\\sigma/\\sqrt{n}}$","$Z = \\dfrac{\\bar{x} - \\mu}{\\sigma\\sqrt{n}}$","$Z = \\dfrac{\\mu - \\bar{x}}{n}$"]'::jsonb, 1, 'The standard error of the mean is $\sigma/\sqrt{n}$.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'When the population variance is unknown, the sample is from a normal population and $n < 30$, the test statistic for a mean follows:', '["the standard normal distribution","Student''s $t$ with $n$ degrees of freedom","Student''s $t$ distribution with $n - 1$ degrees of freedom","the chi-square distribution"]'::jsonb, 2, 'Replacing $\sigma$ with $S$ in a small sample gives a $t$ statistic with $n - 1$ degrees of freedom.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A manufacturer claims bulbs last 1,500 hours with standard deviation 130 hours. A sample of 100 bulbs has mean life 1,465 hours. The value of the test statistic $Z$ is:', '["-1.65","+2.69","-0.35","-2.69"]'::jsonb, 3, '$Z = \dfrac{1465 - 1500}{130/\sqrt{100}} = \dfrac{-35}{13} = -2.69$.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the bulb claim ($H_{0}: \mu = 1500$ against $H_{1}: \mu < 1500$, $\alpha = 0.05$, $Z = -2.69$), the correct decision is:', '["reject $H_{0}$, since $-2.69 < -1.645$","accept $H_{0}$, since $-2.69 < -1.645$","reject $H_{0}$, since $-2.69 > -1.96$","no decision can be made"]'::jsonb, 0, 'The critical value is $-1.645$; the statistic is more extreme, so the claim is rejected.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A sample of 100 has mean 245 and variance 400. Test $H_{0}: \mu = 250$ against $H_{1}: \mu < 250$. The value of $Z$ is:', '["-0.25","-2.50","+2.50","-5.00"]'::jsonb, 1, '$S = 20$, so $Z = \dfrac{245 - 250}{20/10} = -2.50$.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A normal population has mean 17. A sample of 25 has mean 18.1 and estimated variance 16. The test statistic $t$ for $H_{0}: \mu = 17$ is:', '["0.275","1.100","1.375","4.400"]'::jsonb, 2, '$t = \dfrac{18.1 - 17}{4/\sqrt{25}} = \dfrac{1.1}{0.8} = 1.375$.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For $H_{0}: \mu = 17$ against $H_{1}: \mu > 17$ with $t = 1.375$ and $t_{24}(0.05) = 1.711$, the decision is:', '["reject $H_{0}$, because $1.375 > 1$","reject $H_{0}$, because $1.375 < 1.711$","accept $H_{1}$ at the 5% level","accept $H_{0}$, because $1.375 < 1.711$"]'::jsonb, 3, 'The statistic does not reach the critical value, so the difference is attributed to chance.', 'Test of One Mean', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The mean blood pressure of 49 students is 142 (variance 144) and of 64 other students is 148 (variance 256), with known variances. The test statistic for the difference of means is:', '["-2.28","-1.96","+2.28","-0.78"]'::jsonb, 0, '$Z = \dfrac{142 - 148}{\sqrt{144/49 + 256/64}} = \dfrac{-6}{\sqrt{6.939}} = -2.28$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'At $\alpha = 0.05$ the two-tailed critical values for $Z$ are $\pm 1.96$. With $Z = -2.28$, we:', '["accept $H_{0}$ and conclude the means are equal","reject $H_{0}$ and conclude the two population means differ significantly","accept $H_{0}$ because the statistic is negative","cannot decide without the pooled variance"]'::jsonb, 1, '$|-2.28| > 1.96$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two large samples ($n_1 = n_2 = 100$) have means 5.70 and 5.54 and variances 0.36 and 0.40. The $Z$ statistic for $H_{0}: \mu_{1} = \mu_{2}$ is:', '["1.960","0.160","1.835","2.640"]'::jsonb, 2, '$Z = \dfrac{0.16}{\sqrt{0.0076}} = \dfrac{0.16}{0.0872} = 1.835$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Two small samples have $n_{A} = 12$, $S_{A} = 4.5$ and $n_{B} = 10$, $S_{B} = 5.5$. The pooled variance $S_{p}^{2}$ is:', '["25.00","20.25","30.25","24.75"]'::jsonb, 3, '$S_{p}^{2} = \dfrac{(n_A - 1)S_A^{2} + (n_B - 1)S_B^{2}}{n_A + n_B - 2} = \dfrac{11(20.25) + 9(30.25)}{20} = 24.75$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Using that pooled variance with sample means 85 and 81, the test statistic $t$ is:', '["1.878","2.086","0.800","4.000"]'::jsonb, 0, '$t = \dfrac{85 - 81}{\sqrt{24.75(1/12 + 1/10)}} = \dfrac{4}{2.131} = 1.877$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For that test the number of degrees of freedom is:', '["22","20","21","10"]'::jsonb, 1, '$n_1 + n_2 - 2 = 12 + 10 - 2 = 20$.', 'Test of Two Means', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A student claims to get 80% of the problems he attempts correct. He gets 38 out of 50. Under $H_{0}: \pi = 0.80$, the variance of the sample proportion is:', '["0.1600","0.0160","0.0032","0.0080"]'::jsonb, 2, '$\mathrm{Var}(p) = \dfrac{0.8 \times 0.2}{50} = 0.0032$.', 'Test of One Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For that claim, the test statistic $Z$ is:', '["-1.960","+0.707","-2.121","-0.707"]'::jsonb, 3, '$Z = \dfrac{0.76 - 0.80}{\sqrt{0.0032}} = -0.707$.', 'Test of One Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'At $\alpha = 0.05$ (two-tailed) the decision for $Z = -0.707$ is:', '["accept $H_{0}$: the claim is valid","reject $H_{0}$: the claim is false","reject $H_{0}$ because $Z$ is negative","the test is inconclusive"]'::jsonb, 0, '$|-0.707| < 1.96$.', 'Test of One Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A drug is claimed to be 90% effective. In a sample of 200 allergic students it gave relief to 165. For $H_{0}: \pi = 0.9$ against $H_{1}: \pi < 0.9$, $Z$ is:', '["-1.645","-3.536","-2.330","+3.535"]'::jsonb, 1, '$p = 0.825$ and $Z = \dfrac{0.825 - 0.9}{\sqrt{0.9(0.1)/200}} = -3.535$.', 'Test of One Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'At $\alpha = 0.01$ the one-tailed critical value is $-2.33$. For $Z = -3.535$ we:', '["accept $H_{0}$: the manufacturer''s claim is legitimate","accept $H_{0}$ because $|Z| > 2.33$","reject $H_{0}$: the manufacturer''s claim is not legitimate","repeat the test with $\\alpha = 0.05$"]'::jsonb, 2, '$-3.535 < -2.33$ lies in the rejection region.', 'Test of One Proportion', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'To compare two proportions, the pooled proportion is $p_{c} = \dfrac{x_{1} + x_{2}}{n_{1} + n_{2}}$. If 170 of 250 group-O students and 120 of 200 group-A students suffer a disease, $p_{c}$ is:', '["0.68","0.60","0.50","0.64"]'::jsonb, 3, '$p_c = \dfrac{170 + 120}{450} = 0.644 \approx 0.64$.', 'Test of Two Proportions', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For those two groups, the test statistic $Z$ for $H_{0}: \pi_{1} = \pi_{2}$ is approximately:', '["1.76","0.08","2.33","1.20"]'::jsonb, 0, '$Z = \dfrac{0.68 - 0.60}{\sqrt{p_c(1-p_c)(1/250 + 1/200)}} \approx 1.76$.', 'Test of Two Proportions', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'At $\alpha = 0.05$ the one-tailed critical value is 1.645. For $Z \approx 1.76$ on $H_{1}: \pi_{O} > \pi_{A}$, we:', '["accept $H_{0}$: the proportions are equal","reject $H_{0}$: more group-O students suffer from the disease","reject $H_{0}$ only at $\\alpha = 0.01$","cannot decide"]'::jsonb, 1, '$1.76 > 1.645$.', 'Test of Two Proportions', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The ages of five women are 20, 35, 42, 28, 33 and their systolic pressures are 125, 120, 118, 121, 130. The Pearson correlation coefficient between age and pressure is:', '["0.5327","-0.6534","-0.4375","0.4872"]'::jsonb, 2, 'Using $r = \dfrac{n\sum xy - \sum x\sum y}{\sqrt{[n\sum x^{2} - (\sum x)^{2}][n\sum y^{2} - (\sum y)^{2}]}}$ gives the value shown.', 'Correlation Coefficient', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The correlation coefficient $r$ always lies between:', '["0 and 1","$-\\infty$ and $+\\infty$","0 and 100","$-1$ and $+1$"]'::jsonb, 3, 'It is a bounded, unit-free measure of linear association.', 'Correlation Coefficient', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A correlation coefficient of $r = 0$ indicates:', '["no linear relationship between the variables","a perfect positive relationship","a perfect negative relationship","that the variables are independent in every sense"]'::jsonb, 0, 'Zero correlation means no linear association (a non-linear relation may still exist).', 'Correlation Coefficient', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The coefficient of determination is:', '["the square root of the correlation coefficient","the square of the correlation coefficient, $r^{2}$","the same as the slope","always negative"]'::jsonb, 1, '$r^{2}$ is the proportion of the variation in $y$ explained by $x$.', 'Coefficient of Determination', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'If $r = 0.90$, the percentage of the variation in $y$ explained by the variation in $x$ is:', '["90%","9%","81%","19%"]'::jsonb, 2, '$r^{2} = 0.81$, i.e. 81%.', 'Coefficient of Determination', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'In the simple regression line $y = a + bx$, the constant $a$ is called the:', '["slope","residual","correlation","intercept"]'::jsonb, 3, '$a$ is the value of $y$ when $x = 0$; $b$ is the slope.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Given $n = 10$, $\sum x = 56$, $\sum y = 40$, $\sum x^{2} = 524$ and $\sum xy = 364$, the slope $b$ of $y = a + bx$ is:', '["0.665","0.545","0.345","0.945"]'::jsonb, 0, '$b = \dfrac{n\sum xy - \sum x\sum y}{n\sum x^{2} - (\sum x)^{2}} = \dfrac{3640 - 2240}{5240 - 3136} = 0.665$.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the same data, the intercept $a$ is:', '["0.635","0.274","0.567","0.665"]'::jsonb, 1, '$a = (\sum y - b\sum x)/n = (40 - 0.665 \times 56)/10 = 0.274$.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'For the estimated regression $\hat{y} = 120 - 10x$, if $x$ increases by 2 units, $y$ is expected to:', '["increase by 20 units","decrease by 10 units","decrease by 20 units","increase by 100 units"]'::jsonb, 2, 'The slope is $-10$ per unit of $x$, so a rise of 2 gives a change of $-20$.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The method of least squares chooses the regression line by:', '["maximising the sum of the deviations","joining the first and last points","passing through the origin","minimising the sum of the squared vertical deviations of the points from the line"]'::jsonb, 3, 'This is a minimisation technique.', 'Simple Linear Regression', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Covariance between $x$ and $y$ measures:', '["how $x$ and $y$ vary together","the spread of $x$ alone","the mean of $y$","the number of observations"]'::jsonb, 0, 'Positive covariance means they tend to move in the same direction.', 'Correlation Coefficient', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A time series is:', '["a set of observations taken at one point in time","a set of observations of a variable recorded at successive points in time","a list of sample means","a probability distribution"]'::jsonb, 1, 'Examples include monthly sales and yearly rainfall.', 'Time Series Components', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The four components of a time series are:', '["mean, median, mode and range","trend, mean, variance and error","trend, seasonal variation, cyclical variation and irregular variation","level, slope, intercept and residual"]'::jsonb, 2, 'These are the classical components.', 'Time Series Components', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'The long-term upward or downward movement of a series is called its:', '["seasonal variation","irregular variation","cyclical variation","trend"]'::jsonb, 3, 'Trend describes the general direction over a long period.', 'Time Series Components', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'A rise in the sales of children’s wares every Christmas is an example of:', '["seasonal variation","trend","cyclical variation","random variation"]'::jsonb, 0, 'Seasonal variation repeats within a year.', 'Time Series Components', false, 'second', 2),
  ('sta-122-inference-ii', 'STA 122: Inference II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Engineering, Faculty of Biological Sciences', 'Statistics', '100 Level', 'Moving averages are used in time series analysis mainly to:', '["calculate the correlation","smooth out fluctuations and isolate the trend","test a hypothesis","find the mode"]'::jsonb, 1, 'Averaging adjacent values removes short-term variation.', 'Moving Averages', false, 'second', 2),
